import { createOffer, createOfferVersion } from '@projexlight/sdk-offer-catalog';

const offer = await createOffer({
  tenantId, name: 'Pro Plan', slug: 'pro-plan', ownerPersonaId,
});
const version = await createOfferVersion({
  tenantId, offerId: offer.offer_id, version: '2026.1',
  title: 'Pro Plan', price: 99, currency: 'USD',
  body: { seats: 25 },
});
// version.status === 'draft'

import { requestPublishApproval, recordPublishDecision, activateOfferVersion } from '@projexlight/sdk-offer-catalog';

await requestPublishApproval(tenantId, offerId, versionId); // approval_status -> 'pending'
await recordPublishDecision(tenantId, versionId, 'approved');
const live = await activateOfferVersion(tenantId, offerId, versionId);
// live.status === 'live'; any prior live version is now 'retired'

import { resolveCurrentVersion, checkVersionReference } from '@projexlight/sdk-offer-catalog';

const { version, source } = await resolveCurrentVersion(tenantId, offerId);
const pinnedId = version.offer_version_id; // stamp it on the quote

// later, revalidate the pin:
const ref = await checkVersionReference(tenantId, offerId, pinnedId);
if (ref.stale) console.warn(ref.reason, '->', ref.current_offer_version_id);
